const reFence = /^( {0,3})(`{3,}|~{3,})(.*)$/;
const reBq = /^ {0,3}>/;
const reSetext = /^ {0,3}(=+|-+)[ \t]*$/;
const reList = /^( {0,3})(?:([-+*])|(\d{1,9})([.)]))(?=[ \t]|$)/;

