const indentOf = (s) => /^ */.exec(s)[0].length;

// Expand tabs found in the leading whitespace into spaces (tab stop = 4).
function expandIndent(line) {
  const lead = /^[ \t]*/.exec(line)[0];
  if (!lead.includes('\t')) return line;
